Process API enables downloading multiple files in one response, packed together in a TAR archive.

We will get the same image as before, download in the form of digital numbers (DN) as a UINT16 TIFF file. Along with the image we will download the inputMetadata which contains the normalization factor value in a JSON format.

After the download we will be able to convert the INT16 digital numbers to get the FLOAT32 reflectances.

evalscript = """
    //VERSION=3

    function setup() {
        return {
            input: [{
                bands: ["B02", "B03", "B04"],
                units: "DN"
            }],
            output: {
                bands: 3,
                sampleType: "INT16"
            }
        };
    }

    function updateOutputMetadata(scenes, inputMetadata, outputMetadata) {
        outputMetadata.userData = { "norm_factor":  inputMetadata.normalizationFactor }
    }

    function evaluatePixel(sample) {
        return [sample.B04, sample.B03, sample.B02];
    }
"""

request_multitype = SentinelHubRequest(
    evalscript=evalscript,
    input_data=[
        SentinelHubRequest.input_data(
            data_collection=DataCollection.SENTINEL2_L1C,
            time_interval=('2020-06-01', '2020-06-30'),
            mosaicking_order='leastCC'
        )
    ],
    responses=[
        SentinelHubRequest.output_response('default', MimeType.TIFF),
        SentinelHubRequest.output_response('userdata', MimeType.JSON)
    ],
    bbox=betsiboka_bbox,
    size=betsiboka_size,
    config=config
)



# print out information
multi_data = request_multitype.get_data()[0]
multi_data.keys()



# normalize image
img = multi_data['default.tif']
norm_factor = multi_data['userdata.json']['norm_factor']

img_float32 = img * norm_factor



plot_image(img_float32, factor=3.5, clip_range=(0, 1))

All requests so far were built with some helper functions. We can also construct a raw dictionary as defined in the 

API Reference, without these helper functions, so we have full control over building the request body.

request_raw_dict = {
    "input": {
        "bounds": {
            "properties": {
                "crs": betsiboka_bbox.crs.opengis_string
            },
            "bbox": list(betsiboka_bbox)
        },
        "data": [
            {
                "type": "S2L1C",
                "dataFilter": {
                    "timeRange": {"from": '2020-06-01T00:00:00Z', "to": '2020-06-30T00:00:00Z'},
                    "mosaickingOrder": "leastCC",
                }
            }
        ]
    },
    "output": {
        "width": betsiboka_size[0],
        "height": betsiboka_size[1],
        "responses": [
            {
                "identifier": "default",
                "format": {
                    'type': MimeType.TIFF.get_string()
                }
            }
        ]
    },
    "evalscript": evalscript_true_color
}



# create request
download_request = DownloadRequest(
    request_type='POST',
    url="https://services.sentinel-hub.com/api/v1/process",
    post_values=request_raw_dict,
    data_type=MimeType.TIFF,
    headers={'content-type': 'application/json'},
    use_session=True
)

# execute request
client = SentinelHubDownloadClient(config=config)
img = client.download(download_request)



plot_image(img, factor=3.5/255, clip_range=(0,1))

This notebook demonstrates the simplest way to authenticate with the Copernicus Data Space Ecosystem (CDSE), download a Sentinel-2 image, and render it.

import os
import io
import requests
import rasterio
import numpy as np
import matplotlib.pyplot as plt
from datetime import datetime, timedelta
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session



# AUTHENTICATION
# Replace with your actual credentials or ensure environment variables are set
# Please make sure to not share a notebook with filled credentials!
CLIENT_ID = os.getenv("cdse_CLIENT_ID", "your_id_here")
CLIENT_SECRET = os.getenv("cdse_CLIENT_SECRET", "your_secret_here")
TOKEN_URL = "https://identity.dataspace.copernicus.eu/auth/realms/CDSE/protocol/openid-connect/token"

client = BackendApplicationClient(client_id=CLIENT_ID)
oauth = OAuth2Session(client=client)
token = oauth.fetch_token(token_url=TOKEN_URL, client_secret=CLIENT_SECRET, include_client_id=True)
print("Authenticated successfully.")



# 1. Search for the latest cloud-free scene (Max 5% cloud)
search_url = "https://stac.dataspace.copernicus.eu/v1/search"

search_payload = {
    "collections": ["sentinel-2-l2a"],
    "bbox": [16.3, 48.15, 16.4, 48.25],
    "datetime": "2024-04-01T00:00:00Z/2024-06-01T00:00:00Z",
    "query": {
        "eo:cloud_cover": {"lte": 5}
    },
    "limit": 1
}

# Send a POST request with the JSON payload
search_resp = requests.post(search_url, json=search_payload)
search_resp.raise_for_status()

features = search_resp.json().get('features', [])
if not features:
    raise Exception("No scenes found in this range. Try widening the dates.")

# Get the exact timestamp of the found scene
# Note: STAC properties use 'datetime' instead of 'startDate'
found_date = features[0]['properties']['datetime']
print(f"Found valid scene from: {found_date}")




# Parse the found date and create a time window
# We remove the trailing 'Z' to make it compatible with fromisoformat
dt_str = found_date.replace('Z', '')
dt = datetime.fromisoformat(dt_str)

# Create a 1-hour window around the scene
time_from = (dt - timedelta(minutes=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
time_to = (dt + timedelta(minutes=30)).strftime("%Y-%m-%dT%H:%M:%SZ")

print(f"Requesting time window: {time_from} to {time_to}")

# 2. Updated Payload with buffer
evalscript = """
//VERSION=3
function setup() {
    return {
        input: [{ bands: ["B04", "B03", "B02"], units: "DN" }],
        output: { bands: 3, sampleType: "UINT16" }
    };
}
function evaluatePixel(sample) {
    return [sample.B04, sample.B03, sample.B02];
}
"""

payload = {
    "input": {
        "bounds": {
            "bbox": [16.3, 48.15, 16.4, 48.25],
            "properties": {"crs": "http://www.opengis.net/def/crs/EPSG/0/4326"}
        },
        "data": [{
            "type": "sentinel-2-l2a",
            "dataFilter": {
                "timeRange": {
                    "from": time_from,
                    "to": time_to
                }
            }
        }]
    },
    "output": {
        "width": 512, 
        "height": 512,
        "responses": [{"identifier": "default", "format": {"type": "image/tiff"}}]
    },
    "evalscript": evalscript
}

response = oauth.post("https://sh.dataspace.copernicus.eu/api/v1/process", json=payload)
response.raise_for_status()
print("Data retrieved successfully!")



import numpy as np

with rasterio.open(io.BytesIO(response.content)) as src:
    img = src.read().transpose(1, 2, 0)

# Check if we actually have data
print(f"Max pixel value: {img.max()}")
print(f"Mean pixel value: {img.mean()}")

# Scale: 3000 is a good baseline for S2; increase to 2000 for even brighter images
img_display = np.clip(img / 3000, 0, 1)

plt.figure(figsize=(5, 5))
plt.imshow(img_display)
plt.axis('off')
plt.show()

# --- Configuration ---
TARGET_RES = 10 
MAX_PIXELS = 2000 
MAX_WORKERS = 2 
MAX_RETRIES = 3
RETRY_DELAY = 2

@dataclass
class SimpleBBox:
    min_x: float; min_y: float; max_x: float; max_y: float

def split_bbox_into_tiles(bbox):
    w_deg, h_deg = bbox.max_x - bbox.min_x, bbox.max_y - bbox.min_y
    center_lat = (bbox.min_y + bbox.max_y) / 2
    m_lat, m_lon = 111320, 111320 * math.cos(math.radians(center_lat))
    tot_w_px, tot_h_px = int((w_deg * m_lon) / TARGET_RES), int((h_deg * m_lat) / TARGET_RES)
    cols, rows = math.ceil(tot_w_px / MAX_PIXELS), math.ceil(tot_h_px / MAX_PIXELS)

    tiles = []
    print(f"    Tiling: {cols}x{rows} grid")
    for r in range(rows):
        for c in range(cols):
            tiles.append({
                "bbox": SimpleBBox(
                    bbox.min_x + (c * (w_deg/cols)), 
                    bbox.min_y + (r * (h_deg/rows)), 
                    bbox.min_x + ((c+1) * (w_deg/cols)), 
                    bbox.min_y + ((r+1) * (h_deg/rows))
                ),
                "size": (int(tot_w_px/cols), int(tot_h_px/rows)),
                "index": (r, c)
            })
    return tiles

